$ErrorActionPreference='Continue';function S([string]$l,[string]$m){Write-Host "[$l] $m"};function P([int]$p,[string]$n){if((Test-NetConnection 127.0.0.1 -Port $p -WarningAction SilentlyContinue).TcpTestSucceeded){S OK "$n reachable on $p"}else{S FAILED "$n unavailable on $p"}};function U([string]$u,[string]$n){try{$r=Invoke-WebRequest $u -UseBasicParsing -TimeoutSec 8;if($r.StatusCode-lt 500){S OK "$n reachable ($($r.StatusCode))"}else{S WARN "$n returned $($r.StatusCode)"}}catch{S FAILED "$n unavailable"}};if(Get-Command docker -ErrorAction SilentlyContinue){docker info *> $null;if($LASTEXITCODE-eq 0){S OK 'Docker Desktop ready'}else{S FAILED 'Docker Desktop unavailable'}}else{S FAILED 'Docker CLI not found'};P 15432 PostgreSQL;P 6379 Redis;P 9000 'RustFS API';P 9876 'RocketMQ NameServer';if((Test-NetConnection 127.0.0.1 -Port 11434 -WarningAction SilentlyContinue).TcpTestSucceeded){S OK 'Ollama listening on 11434'}else{S WARN 'Ollama unavailable (optional)'};U 'http://127.0.0.1:9090/api/ragent/' 'ragent backend';P 5173 'ragent frontend'
